sys_variable_value.value:
// ATF-CP-UI-07: Customer Portal Navigation
await sn_atf.navigate('/x_2056099_indust_0_customer_portal.do#dashboard');
await sn_atf.delay(3000);
var navTargets = [
    { tab: 'Catalog', heading: 'Product Catalog' },
    { tab: 'My Orders', heading: 'My Orders' },
    { tab: 'Delivery', heading: 'Delivery Tracking' },
    { tab: 'Surveys', heading: 'Customer Survey' },
    { tab: 'Profile', heading: 'My Profile' },
    { tab: 'Dashboard', heading: 'Dashboard' },
];
for (var i = 0; i < navTargets.length; i++) {
    var target = navTargets[i];
    var tabs = await screen.findAllByText(target.tab, { exact: true });
    var navTab = null;
    for (var j = 0; j < tabs.length; j++) {
        if (tabs[j].tagName === 'BUTTON' || tabs[j].closest('nav')) {
            navTab = tabs[j];
            break;
        }
    }
    if (!navTab) navTab = tabs[0];
    await user.click(navTab);
    await sn_atf.delay(2000);
    var headingEl = await screen.queryByText(target.heading, { exact: false });
    var notLinkedEl = await screen.queryByText('Customer Account Not Linked');
    if (headingEl) {
        expect(headingEl).toBeVisible();
    } else if (notLinkedEl) {
        expect(notLinkedEl).toBeVisible();
    }
}
